{
  "name": "@josxa/opencode-recall",
  "version": "1.1.3",
  "description": "OpenCode plugin that adds semantic + lexical recall over your local session history, with cursor-paginated ChatML transcript reads.",
  "type": "module",
  "packageManager": "pnpm@11.9.0",
  "sideEffects": false,
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./sdk": {
      "types": "./dist/src/sdk.d.ts",
      "default": "./dist/src/sdk.js"
    }
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "engines": {
    "node": ">=22.13.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "history",
    "recall",
    "search",
    "semantic-search",
    "embeddings",
    "ollama",
    "chatml"
  ],
  "author": "JosXa <info@josxa.dev>",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JosXa/opencode-recall.git"
  },
  "bugs": {
    "url": "https://github.com/JosXa/opencode-recall/issues"
  },
  "homepage": "https://github.com/JosXa/opencode-recall#readme",
  "scripts": {
    "clean": "node -e \"import('node:fs').then(({ rmSync }) => rmSync('dist', { recursive: true, force: true }))\"",
    "build": "pnpm run clean && tsc -p tsconfig.build.json",
    "test": "vitest run && pnpm run test:federated-worker",
    "test:federated-worker": "pnpm run build && node --test test/federated-worker.node-test.mjs",
    "benchmark:sync": "tsx scripts/benchmark-sync.ts",
    "eval:real-history": "tsx scripts/evaluate-real-history.ts",
    "eval:embeddings": "tsx scripts/evaluate-embedding-models.ts",
    "typecheck": "tsc --noEmit",
    "lint": "biome check --error-on-warnings .",
    "format": "biome check --write .",
    "ai:check": "biome check --write --error-on-warnings . && tsc --noEmit",
    "prepare": "husky",
    "prepublishOnly": "pnpm run build"
  },
  "files": [
    "dist",
    "prompts",
    "schema"
  ],
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "devDependencies": {
    "@biomejs/biome": "2.5.1",
    "@opencode-ai/plugin": "latest",
    "@types/node": "latest",
    "husky": "latest",
    "tsx": "latest",
    "typescript": "^7.0.2",
    "vitest": "latest"
  },
  "dependencies": {
    "sqlite-vec": "0.1.9"
  }
}
